   136→    pub async fn connect_public(&self, symbols: Vec<String>, tx: mpsc::Sender<WsEvent>) -> Result<()> {
   137→        let (ws_stream, _) = connect_async(&self.public_url).await?;
   138→        let (mut write, mut read) = ws_stream.split();
   139→
   140→        let topics: Vec<String> = symbols
   141→            .iter()
   142→            .map(|s| format!("tickers.{}", s))
   143→            .collect();
   144→
   145→        let sub = SubscribeMessage {
   146→            op: "subscribe".to_string(),
   147→            args: topics,
   148→        };
   149→        write.send(Message::Text(serde_json::to_string(&sub)?)).await?;
   150→
   151→        tokio::spawn(async move {
   152→            let mut ping_interval = tokio::time::interval(std::time::Duration::from_secs(20));
   153→            loop {
   154→                ping_interval.tick().await;
   155→                if write.send(Message::Text(r#"{"op":"ping"}"#.to_string())).await.is_err() {
   156→                    break;
   157→                }
   158→            }
   159→        });
   160→
   161→        while let Some(msg) = read.next().await {
   162→            match msg {
   163→                Ok(Message::Text(text)) => {
   164→                    if let Ok(ws_msg) = serde_json::from_str::<WsMessage>(&text) {
   165→                        if let Some(topic) = &ws_msg.topic {
   166→                            if topic.starts_with("tickers.") {
   167→                                if let Some(data) = ws_msg.data {
   168→                                    let _ = tx.send(WsEvent::TickerUpdate(data)).await;
   169→                                }
   170→                            }
   171→                        }
   172→                    }
   173→                }
   174→                Ok(Message::Close(_)) => break,
   175→                Err(_) => break,
   176→                _ => {}
   177→            }
   178→        }
   179→
   180→        Ok(())
   181→    }
