   183→    pub async fn connect_chart(
   184→        &self,
   185→        symbol: &str,
   186→        interval: &str,
   187→        tx: mpsc::Sender<WsEvent>,
   188→    ) -> Result<()> {
   189→        let (ws_stream, _) = connect_async(&self.public_url).await?;
   190→        let (mut write, mut read) = ws_stream.split();
   191→
   192→        let topics = vec![
   193→            format!("kline.{}.{}", interval, symbol),
   194→            format!("publicTrade.{}", symbol),
   195→        ];
   196→
   197→        let sub = SubscribeMessage {
   198→            op: "subscribe".to_string(),
   199→            args: topics,
   200→        };
   201→        write
   202→            .send(Message::Text(serde_json::to_string(&sub)?))
   203→            .await?;
   204→
   205→        let _ = tx.send(WsEvent::Connected).await;
   206→
   207→        tokio::spawn(async move {
   208→            let mut ping_interval = tokio::time::interval(std::time::Duration::from_secs(20));
   209→            loop {
   210→                ping_interval.tick().await;
   211→                if write
   212→                    .send(Message::Text(r#"{"op":"ping"}"#.to_string()))
   213→                    .await
   214→                    .is_err()
   215→                {
   216→                    break;
   217→                }
   218→            }
   219→        });
   220→
   221→        while let Some(msg) = read.next().await {
   222→            match msg {
   223→                Ok(Message::Text(text)) => {
   224→                    if let Ok(ws_msg) = serde_json::from_str::<WsMessage>(&text) {
   225→                        if let Some(topic) = &ws_msg.topic {
   226→                            if let Some(data) = ws_msg.data {
   227→                                if topic.starts_with("kline.") {
   228→                                    let _ = tx.send(WsEvent::KlineUpdate(data)).await;
   229→                                } else if topic.starts_with("publicTrade.") {
   230→                                    let _ = tx.send(WsEvent::TradeUpdate(data)).await;
   231→                                }
   232→                            }
   233→                        }
   234→                    }
   235→                }
   236→                Ok(Message::Close(_)) => {
   237→                    let _ = tx.send(WsEvent::Disconnected).await;
   238→                    break;
   239→                }
   240→                Err(_) => {
   241→                    let _ = tx.send(WsEvent::Disconnected).await;
   242→                    break;
   243→                }
   244→                _ => {}
   245→            }
   246→        }
   247→
   248→        Ok(())
   249→    }
   250→}
