   191→fn parse_trade(data: &serde_json::Value) -> Option<Trade> {
   192→    let timestamp = data.get("T")?.as_i64()?;
   193→    let price = Decimal::from_str(data.get("p")?.as_str()?).ok()?;
   194→    let qty = Decimal::from_str(data.get("v")?.as_str()?).ok()?;
   195→    let side_str = data.get("S")?.as_str()?;
   196→    let side = if side_str == "Buy" { Side::Buy } else { Side::Sell };
   197→    
   198→    Some(Trade {
   199→        timestamp,
   200→        price,
   201→        qty,
   202→        side,
   203→    })
   204→}
   205→
   206→fn parse_candle(data: &serde_json::Value) -> Option<trade_shared::Candle> {
   207→    let start = data.get("start")?.as_i64()?;
   208→    let open = Decimal::from_str(data.get("open")?.as_str()?).ok()?;
   209→    let high = Decimal::from_str(data.get("high")?.as_str()?).ok()?;
   210→    let low = Decimal::from_str(data.get("low")?.as_str()?).ok()?;
   211→    let close = Decimal::from_str(data.get("close")?.as_str()?).ok()?;
   212→    let volume = Decimal::from_str(data.get("volume")?.as_str()?).ok()?;
   213→    
   214→    Some(trade_shared::Candle {
   215→        timestamp: start,
   216→        open,
   217→        high,
   218→        low,
   219→        close,
   220→        volume,
   221→    })
   222→}
